#import <Cocoa/Cocoa.h>
typedef NSObject *nw_proxy_config_t;
#import <WebKit/WebKit.h>
#import <sys/socket.h>
#import <netinet/in.h>
#import <unistd.h>
#import "TrackpadBridge.h"

static WKWebView *browser;
static NSString *siteRoot;
static NSString *mimeType(NSString *path){NSDictionary*m=@{@"html":@"text/html; charset=utf-8",@"js":@"text/javascript",@"css":@"text/css",@"json":@"application/json",@"png":@"image/png",@"jpg":@"image/jpeg",@"jpeg":@"image/jpeg",@"svg":@"image/svg+xml",@"woff2":@"font/woff2",@"mp3":@"audio/mpeg",@"glb":@"model/gltf-binary"};return m[path.pathExtension.lowercaseString]?:@"application/octet-stream";}
static void startServer(void){dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{int server=socket(AF_INET,SOCK_STREAM,0),yes=1;setsockopt(server,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));struct sockaddr_in addr={.sin_family=AF_INET,.sin_port=htons(47321),.sin_addr.s_addr=htonl(INADDR_LOOPBACK)};if(bind(server,(struct sockaddr*)&addr,sizeof(addr))<0||listen(server,32)<0)return;for(;;){int client=accept(server,NULL,NULL);if(client<0)continue;char buffer[16384]={0};ssize_t size=read(client,buffer,sizeof(buffer)-1);if(size<=0){close(client);continue;}NSString*request=[[NSString alloc]initWithBytes:buffer length:size encoding:NSUTF8StringEncoding];NSArray*parts=[[request componentsSeparatedByString:@"\r\n"].firstObject componentsSeparatedByString:@" "];NSString*raw=parts.count>1?parts[1]:@"/";raw=[[raw componentsSeparatedByString:@"?"]firstObject].stringByRemovingPercentEncoding;if([raw containsString:@".."]){close(client);continue;}NSString*relative=[raw isEqualToString:@"/"]?@"index.html":[raw substringFromIndex:1];NSString*path=[siteRoot stringByAppendingPathComponent:relative];BOOL isDir=NO;if([[NSFileManager defaultManager]fileExistsAtPath:path isDirectory:&isDir]&&isDir)path=[path stringByAppendingPathComponent:@"index.html"];NSData*body=[NSData dataWithContentsOfFile:path];NSString*status=body?@"200 OK":@"404 Not Found";if(!body)body=[@"Not found" dataUsingEncoding:NSUTF8StringEncoding];NSString*header=[NSString stringWithFormat:@"HTTP/1.1 %@\r\nContent-Type: %@\r\nContent-Length: %lu\r\nCache-Control: no-cache\r\nConnection: close\r\n\r\n",status,mimeType(path),(unsigned long)body.length];write(client,header.UTF8String,strlen(header.UTF8String));write(client,body.bytes,body.length);close(client);}});}
static void trackpad(const char*json){NSString*payload=[NSString stringWithUTF8String:json];dispatch_async(dispatch_get_main_queue(),^{NSString*script=[NSString stringWithFormat:@"window.__rodSpaceNativeTrackpad?.update(%@);window.__rodSpaceNativeScale?.update(%@);",payload,payload];[browser evaluateJavaScript:script completionHandler:nil];});}
@interface AppDelegate:NSObject<NSApplicationDelegate>@property NSWindow*window;@end
@implementation AppDelegate
-(void)applicationDidFinishLaunching:(NSNotification*)note{siteRoot=[NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:@"rod-space"];startServer();WKWebViewConfiguration*config=[WKWebViewConfiguration new];[config.userContentController addUserScript:[[WKUserScript alloc]initWithSource:@"window.__rodSpaceMacApp=true;" injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:NO]];browser=[[WKWebView alloc]initWithFrame:NSZeroRect configuration:config];self.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,1280,800) styleMask:NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskMiniaturizable|NSWindowStyleMaskResizable backing:NSBackingStoreBuffered defer:NO];self.window.title=@"Rod Space";self.window.contentView=browser;[self.window center];[self.window makeKeyAndOrderFront:nil];[browser loadRequest:[NSURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:47321/index.html"]]];RSStartTrackpad(trackpad);[NSApp activateIgnoringOtherApps:YES];}
-(void)applicationWillTerminate:(NSNotification*)note{RSStopTrackpad();}-(BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication*)sender{return YES;}
@end
int main(int argc,const char*argv[]){@autoreleasepool{NSApplication*app=NSApplication.sharedApplication;AppDelegate*delegate=[AppDelegate new];app.delegate=delegate;[app setActivationPolicy:NSApplicationActivationPolicyRegular];[app run];}return 0;}
